import {PRODUCTS,SIZES,money,getProduct,escapeHtml as esc,prettyDate,dateStatus,datesFor,deliveryFor,unitPrice,bagTotals,sanitizeBag,filterProducts,recommend} from './shop.js';

const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const BAG_KEY='petal-stem-bag-v1';
let storageAvailable=true;
function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let bag=sanitizeBag(readStorage(BAG_KEY,[]));
let currentProduct=null,verifiedDelivery=null,toastTimer;
let finder={step:0,occasion:'Just Because',style:'soft',budget:'65'};
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function saveStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;toast('Your browser cannot save this. Your choices will remain for this visit only.');return false;}}
function saveBag(){saveStorage(BAG_KEY,bag);updateBagCount();}
function updateBagCount(){const count=bagTotals(bag).count;$('.bag-count').textContent=count;$('.bag-button').setAttribute('aria-label',`Open shopping bag, ${count} ${count===1?'item':'items'}`);}
function openDialog(id){$$('dialog[open]').forEach(d=>d.close());const dialog=$('#'+id);dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}
function closeDialog(dialog){dialog.close();document.body.classList.toggle('modal-open',$$('dialog[open]').length>0);}
$$('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>document.body.classList.toggle('modal-open',$$('dialog[open]').length>0));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(dialog);}});});

function productCard(p){return `<article class="product-card"><a href="#bouquet/${p.id}" class="product-image-link" aria-label="Explore ${p.name}, from ${money(p.price)}"><img src="assets/${p.id}.webp" srcset="assets/${p.id}-small.webp 480w, assets/${p.id}.webp 1122w" sizes="(max-width:600px) 45vw, (max-width:800px) 44vw, 22vw" width="1122" height="1402" loading="lazy" alt="${p.alt}">${p.tag?`<span class="product-tag">${p.tag}</span>`:''}<span class="product-view-label" aria-hidden="true">↗</span></a><div class="product-card-header"><h3><a href="#bouquet/${p.id}">${p.name}</a></h3><span class="price">From ${money(p.price)}</span></div><p class="product-description">${p.short}</p><div class="color-dots" role="img" aria-label="${p.palette}">${p.swatches.map(color=>`<span style="background:${color}"></span>`).join('')}</div></article>`;}
function renderCollection(){const values=Object.fromEntries(new FormData($('#filters')));const products=filterProducts(values);$('#product-grid').innerHTML=products.length?products.map(productCard).join(''):'<div class="no-results"><h3>A different kind of lovely?</h3><p>No bouquets match all of these filters. Try a wider budget or another palette.</p><button class="text-link" data-action="reset-filters">See all flowers →</button></div>';const count=Object.values(values).filter(Boolean).length;$('#filter-count').textContent=count?` (${count})`:'';$('#collection-status').textContent=`${products.length} ${products.length===1?'bouquet matches':'bouquets match'} your filters.`;}
function showFilters(show=true){$('#filters').hidden=!show;$('.filter-toggle').setAttribute('aria-expanded',String(show));}
function resetFilters(){$('#filters').reset();renderCollection();}
$('#filters').addEventListener('change',renderCollection);
$('#filters').addEventListener('reset',()=>setTimeout(renderCollection));

function dateOptions(product,selected=''){const options=datesFor(product);return `<option value="">Choose an available date</option>${selected&&!options.some(d=>d.date===selected)?`<option selected disabled value="${esc(selected)}">${esc(selected)} — please update</option>`:''}${options.map(d=>`<option value="${d.date}" ${d.reason?'disabled':''} ${d.date===selected?'selected':''}>${prettyDate(d.date)}${d.reason?` — ${d.reason.includes('fully booked')?'fully booked':d.reason.includes('closed')?'studio closed':'not available'}`:''}</option>`).join('')}`;}
function renderProduct(p){currentProduct=p;verifiedDelivery=null;document.title=`${p.name} — Petal & Stem`;
$('#product-view').innerHTML=`<article class="product-page"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="#home">Home</a><span>/</span><a href="#collection">Seasonal bouquets</a><span>/</span><span aria-current="page">${p.name}</span></nav><div class="product-layout"><div class="product-gallery"><img class="gallery-main" id="gallery-main" src="assets/${p.id}.webp" width="1122" height="1402" alt="${p.alt}"><div class="gallery-thumbs" role="group" aria-label="Bouquet photographs"><button data-photo="${p.id}" aria-label="View the whole bouquet" aria-pressed="true"><img src="assets/${p.id}-small.webp" alt="" width="72" height="85"></button><button data-photo="${p.id}-detail" aria-label="View the bouquet from above" aria-pressed="false"><img src="assets/${p.id}-detail.webp" alt="" width="72" height="85"></button></div><p class="gallery-caption" id="gallery-caption">The Classic size, wrapped and ready to give. Vase not included.</p></div><div class="product-info"><p class="eyebrow">A LITTLE SOMETHING, BEAUTIFULLY SAID</p><h1 tabindex="-1">${p.name}</h1><p class="product-lead">${p.description}</p><div class="product-price-row"><span class="product-price" id="product-price">${money(p.price+20)}</span><span>USD · Handwritten card included</span></div><dl class="product-specs"><dt>The flowers</dt><dd>${p.varieties}</dd><dt>The palette</dt><dd>${p.palette}</dd><dt>The size</dt><dd id="product-dimensions">${SIZES.classic.dimensions}</dd></dl><p class="substitution-note">A note on the season: individual varieties may change with availability. We’ll keep the palette, size, and feeling, substituting stems of equal or greater value. Photos are illustrative.</p><form id="purchase-form"><fieldset><legend>Choose your size</legend><div class="choice-grid size-grid">${Object.entries(SIZES).map(([key,size])=>`<label><input type="radio" name="size" value="${key}" ${key==='classic'?'checked':''}><span>${size.name} · ${money(p.price+size.extra)}<small>${size.stems}</small></span></label>`).join('')}</div><p id="size-description" class="size-description">${SIZES.classic.description}</p></fieldset><div class="delivery-check"><label for="delivery-zip">Let’s check the doorstep.</label><div class="zip-row"><input id="delivery-zip" name="zip" type="text" inputmode="numeric" autocomplete="postal-code" maxlength="5" pattern="[0-9]{5}" placeholder="Delivery ZIP code" aria-describedby="delivery-status" required><button type="button" class="button" data-action="check-zip">Check ZIP</button></div><p id="delivery-status" class="delivery-status" role="status">Sample Portland delivery · Try 97201–97206.<br>Delivery is $6–$9 per bouquet, shown before you add to bag.</p></div><label class="field-label" for="delivery-date">A lovely day to receive flowers</label><select id="delivery-date" name="date" required disabled aria-describedby="date-help">${dateOptions(p)}</select><p id="date-help" class="field-hint">Check your ZIP first. ${p.lead} days’ notice · Tuesday–Saturday · 9am–6pm. Dates use Portland time.</p><label class="gift-label" for="gift-message">Your words, in our handwriting <span><span id="message-count">0</span>/240</span></label><textarea id="gift-message" name="message" maxlength="240" rows="3" placeholder="A little note to make their day…" aria-describedby="gift-help"></textarea><p id="gift-help" class="field-hint">Optional. Don’t forget to sign your name. Your card is included.</p><label class="add-vase"><input name="vase" type="checkbox"><span>Add a simple glass vase · $18<small>20cm tall × 12cm wide. Bouquet arrives ready to arrange.</small></span></label><div class="purchase-total"><span>Bouquet & extras</span><span id="purchase-subtotal">${money(p.price+20)}</span></div><div class="purchase-total"><span>Sample delivery</span><span id="purchase-delivery">Check ZIP above</span></div><p id="purchase-error" class="error-text" role="alert" hidden></p><button id="add-to-bag" class="button full-width" type="submit" disabled><span id="add-label">Check delivery to add to bag</span><span aria-hidden="true">↗</span></button><p class="purchase-note">Sample shop · No payment is taken. Your bag is saved on this browser.</p></form><div class="faq-list"><details><summary>What arrives at their door?<span aria-hidden="true">+</span></summary><p>A hand-tied bouquet wrapped in tissue and kraft paper, a care note, and your handwritten card. Photos show Classic size. No vase is included unless you select the optional clear glass vase. Decorative studio ceramics are not part of this purchase.</p></details><details><summary>A little care goes a long way<span aria-hidden="true">+</span></summary><p>Trim 1–2cm from each stem and place in a clean vase of fresh water. Remove submerged leaves, refresh water every two days, and keep away from heat and direct sun. These flowers are decorative, not edible; keep away from pets.</p></details><details><summary>Delivery & seasonal substitutions<span aria-hidden="true">+</span></summary><p>Our sample delivery window is 9am–6pm, Tuesday–Saturday. Each bouquet is charged its own delivery fee, even when sharing a destination. Seasonal substitutions preserve the bouquet’s palette, size, and value. Live stock, delivery capacity, and payment services still need to be connected.</p></details></div></div></div><section class="related-products" aria-labelledby="related-title"><p class="eyebrow">A FEW MORE LOVELY POSSIBILITIES</p><h2 id="related-title">There’s a feeling for everyone.</h2><div class="product-grid">${PRODUCTS.filter(other=>other.id!==p.id).map(productCard).join('')}</div></section></article>`;
$('#purchase-form').addEventListener('submit',addToBag);
$('#purchase-form').addEventListener('change',updatePurchase);
$('#delivery-zip').addEventListener('input',()=>{verifiedDelivery=null;$('#delivery-date').disabled=true;$('#delivery-status').className='delivery-status';$('#delivery-status').textContent='Check this ZIP to see sample delivery prices and available dates.';updatePurchase();});
$('#delivery-zip').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();checkZip();}});
$('#gift-message').addEventListener('input',()=>$('#message-count').textContent=$('#gift-message').value.length);
}
function checkZip(){const result=deliveryFor($('#delivery-zip').value);verifiedDelivery=result.ok?result:null;$('#delivery-status').textContent=result.message;$('#delivery-status').className=`delivery-status ${result.ok?'success':'error'}`;$('#delivery-zip').setAttribute('aria-invalid',String(!result.ok));$('#delivery-date').disabled=!result.ok;updatePurchase();if(result.ok)$('#delivery-date').focus();}
function selectedPurchase(){const values=new FormData($('#purchase-form'));return {product:currentProduct.id,size:values.get('size'),vase:values.get('vase')==='on',zip:$('#delivery-zip').value.trim(),date:values.get('date')||'',message:values.get('message').trim(),quantity:1};}
function updatePurchase(){if(!$('#purchase-form'))return;const item=selectedPurchase(),size=SIZES[item.size],price=unitPrice(item);$('#product-price').textContent=money(price);$('#product-dimensions').textContent=size.dimensions;$('#size-description').textContent=size.description;$('#purchase-subtotal').textContent=money(price);$('#purchase-delivery').textContent=verifiedDelivery?money(verifiedDelivery.fee):'Check ZIP above';const error=item.date?dateStatus(item.date,currentProduct):'';$('#purchase-error').textContent=error;$('#purchase-error').hidden=!error;const valid=verifiedDelivery&&verifiedDelivery.zip===item.zip&&item.date&&!error;$('#add-to-bag').disabled=!valid;$('#add-label').textContent=!verifiedDelivery?'Check delivery to add to bag':!item.date?'Choose a delivery date':error?'Choose another delivery date':`Add to bag · ${money(price+verifiedDelivery.fee)}`;}
function addToBag(event){event.preventDefault();const item=selectedPurchase();if(!verifiedDelivery||verifiedDelivery.zip!==item.zip||!deliveryFor(item.zip).ok||dateStatus(item.date,currentProduct)){updatePurchase();return;}const existing=bag.find(i=>i.product===item.product&&i.size===item.size&&i.vase===item.vase&&i.zip===item.zip&&i.date===item.date&&i.message===item.message);if(existing?.quantity===9){toast('You have 9 of this arrangement in your bag, the sample limit.');return;}if(bag.length>=30&&!existing){toast('Your sample bag is full. Remove an item before adding another.');return;}if(existing)existing.quantity++;else bag.push({...item,id:crypto.randomUUID()});saveBag();renderBag();openDialog('bag-dialog');toast(`${currentProduct.name} is in your bag.`);}

function renderBag(){if(!bag.length){$('#bag-content').innerHTML='<div class="empty-bag"><span aria-hidden="true">✳</span><h3>Room for something lovely.</h3><p>Your bag is waiting for a little color.</p><a class="button" data-close href="#collection">Find your flowers <span aria-hidden="true">↗</span></a></div>';return;}
const totals=bagTotals(bag),invalid=bag.some(item=>dateStatus(item.date,getProduct(item.product)));
$('#bag-content').innerHTML=bag.map(item=>{const p=getProduct(item.product),error=dateStatus(item.date,p);return `<article class="bag-item" data-item="${esc(item.id)}"><div class="bag-item-main"><a href="#bouquet/${p.id}" data-close aria-label="View ${p.name}"><img src="assets/${p.id}-small.webp" alt="${p.alt}" width="90" height="115"></a><div><h3>${p.name}</h3><p>${SIZES[item.size].name}${item.vase?' · with glass vase':''}</p><p>ZIP ${item.zip} · ${money(deliveryFor(item.zip).fee)} delivery each</p><div class="quantity-control"><button data-bag-command="decrease" aria-label="Decrease ${p.name} quantity" ${item.quantity<=1?'disabled':''}>−</button><output aria-label="Quantity">${item.quantity}</output><button data-bag-command="increase" aria-label="Increase ${p.name} quantity" ${item.quantity>=9?'disabled':''}>+</button></div></div><div class="bag-item-price">${money(unitPrice(item)*item.quantity)}<button class="remove-item" data-bag-command="remove" aria-label="Remove ${p.name}">Remove</button></div></div><label class="field-label" style="margin-top:16px" for="date-${esc(item.id)}">Delivery date</label><select id="date-${esc(item.id)}" data-bag-date aria-describedby="bag-date-status-${esc(item.id)}">${dateOptions(p,item.date)}</select><p class="${error?'error-text':'field-hint'}" id="bag-date-status-${esc(item.id)}">${error||'Sample delivery window: 9am–6pm'}</p><details class="bag-message"><summary>${item.message?'Edit your gift message':'Add a gift message'}</summary><label class="sr-only" for="message-${esc(item.id)}">Gift message for ${p.name}</label><textarea id="message-${esc(item.id)}" maxlength="240" rows="3">${esc(item.message)}</textarea><button class="text-link" data-bag-command="message">Save message <span aria-hidden="true">→</span></button></details></article>`;}).join('')+`<div class="bag-totals"><div><span>Bouquets & extras</span><span>${money(totals.subtotal)}</span></div><div><span>Sample delivery · per bouquet</span><span>${money(totals.delivery)}</span></div><div><span>Sample tax estimate</span><span>$0</span></div><div class="grand-total"><span>Sample total</span><span>${money(totals.total)}</span></div>${invalid?'<p class="notice error">A saved delivery date is no longer available. Choose a new date above to review your bag.</p>':''}<button class="button full-width" data-action="review" ${invalid?'disabled':''}>Review sample bag <span aria-hidden="true">↗</span></button><p class="fine-print">Payment, live delivery, and final tax calculations are not connected. No order can be placed. ${storageAvailable?'Your bag is saved on this browser.':'Browser storage is unavailable; your bag lasts for this visit only.'}</p></div>`;
}
function bagCommand(button){const element=button.closest('[data-item]'),item=bag.find(i=>i.id===element.dataset.item);if(!item)return;const command=button.dataset.bagCommand;
if(command==='message'){item.message=element.querySelector('textarea').value.slice(0,240);saveBag();element.querySelector('summary').textContent=item.message?'Edit your gift message':'Add a gift message';element.querySelector('details').open=false;element.querySelector('summary').focus();toast('Your gift message has been saved.');return;}
if(command==='remove'){bag=bag.filter(i=>i.id!==item.id);toast(`${getProduct(item.product).name} removed from your bag.`);}else item.quantity=Math.max(1,Math.min(9,item.quantity+(command==='increase'?1:-1)));
saveBag();renderBag();const newButton=$(`[data-item="${item.id}"] [data-bag-command="${command}"]`);if(newButton&&!newButton.disabled)newButton.focus();else $('#bag-dialog .close-button').focus();}
$('#bag-content').addEventListener('change',event=>{if(event.target.matches('[data-bag-date]')){const item=bag.find(i=>i.id===event.target.closest('[data-item]').dataset.item);if(!item)return;item.date=event.target.value;saveBag();renderBag();$(`#date-${item.id}`)?.focus();}});
function reviewBag(){const invalid=bag.some(item=>dateStatus(item.date,getProduct(item.product)));if(!bag.length||invalid){renderBag();return;}const totals=bagTotals(bag);$('#info-content').innerHTML=`<h2 id="info-title">A lovely selection.<br>Just a sample for now.</h2><p>This is a preview of your bag, not an order. Payments and live delivery services are not connected.</p><ul class="review-list">${bag.map(item=>`<li><strong>${item.quantity} × ${getProduct(item.product).name}</strong>${SIZES[item.size].name}${item.vase?' + glass vase':''} · ${prettyDate(item.date)} · ZIP ${item.zip}${item.message?`<br>Gift note: “${esc(item.message)}”`:''}</li>`).join('')}</ul><div class="soft-panel"><strong>Sample total: ${money(totals.total)}</strong>Includes ${money(totals.delivery)} illustrative delivery fees and a $0 sample tax estimate. Live prices and availability must be verified before a real purchase.</div><p>No payment details have been requested. No order has been placed or confirmed. Guest checkout can be offered when a payment provider is connected.</p><button class="button full-width" data-action="bag">Back to my bag <span aria-hidden="true">→</span></button>`;openDialog('info-dialog');}

const finderSteps=[{key:'occasion',title:'What’s the occasion?',copy:'Big moments, small gestures. They all deserve flowers.',choices:['Happy Birthday','Thank You','Thinking of You','Congratulations','Just Because']},{key:'style',title:'What feels like them?',copy:'A palette, a personality, a little instinct.',choices:[['soft','Soft & understated'],['bright','Bright & joyful'],['wild','Wild & unexpected']]},{key:'budget',title:'A comfortable little budget?',copy:'Bouquet prices before a vase or delivery. Sample delivery adds $6–$9 per bouquet.',choices:[['50','Up to $50'],['65','Up to $65'],['80','Up to $80']]}];
function renderFinder(){const content=$('#finder-content');if(finder.step===3){const results=recommend(finder);content.innerHTML=`<p class="eyebrow">A LITTLE FLORAL INTUITION</p><h2 id="finder-title">These feel like you.</h2><p>Our closest matches within your ${money(Number(finder.budget))} bouquet budget, chosen for the occasion and mood. Prices below are for Petite, before delivery.</p>${results.map(p=>`<div class="finder-result"><img src="assets/${p.id}-small.webp" alt="${p.alt}" width="140" height="175"><div><h3>${p.name}</h3><p>${p.short}<br>From ${money(p.price)} · ${p.palette}</p><a class="text-link" data-close href="#bouquet/${p.id}">Meet your bouquet <span aria-hidden="true">↗</span></a></div></div>`).join('')}<button class="text-link" data-action="finder-restart">Start again <span aria-hidden="true">↻</span></button>`;return;}
const step=finderSteps[finder.step];content.innerHTML=`<div class="finder-progress" role="img" aria-label="Step ${finder.step+1} of 3">${[0,1,2].map(i=>`<span class="${i<=finder.step?'active':''}"></span>`).join('')}</div><p class="eyebrow">STEP ${finder.step+1} OF 3</p><h2 id="finder-title">${step.title}</h2><p>${step.copy}</p><form id="finder-form"><fieldset><legend class="sr-only">${step.title}</legend><div class="choice-grid">${step.choices.map(choice=>{const [value,label]=Array.isArray(choice)?choice:[choice,choice];return `<label><input name="answer" type="radio" value="${value}" ${finder[step.key]===value?'checked':''} required><span>${label}</span></label>`;}).join('')}</div></fieldset><div class="finder-actions">${finder.step?'<button type="button" class="text-link" data-action="finder-back">← Back</button>':'<span></span>'}<button class="button" type="submit">${finder.step===2?'Find my flowers':'A little further'} <span aria-hidden="true">→</span></button></div></form>`;
$('#finder-form').addEventListener('submit',event=>{event.preventDefault();finder[step.key]=new FormData(event.target).get('answer');finder.step++;renderFinder();focusFinder();});}
function focusFinder(){$('#finder-title').setAttribute('tabindex','-1');$('#finder-title').focus();}
function openFinder(){finder.step=0;renderFinder();openDialog('finder-dialog');}

const policies={care:{title:'A little care. More lovely days.',copy:'Unwrap your bouquet as soon as it arrives. Trim 1–2cm from the stems at an angle and place in a clean vase of cool, fresh water. Remove any leaves below the waterline. Refresh the water every two days and trim stems again as needed. Keep flowers away from direct sun, radiators, and ripening fruit. Remove fading stems to help the rest of the bouquet. Flowers are for decoration, not eating; keep out of reach of pets and small children.'},returns:{title:'Every stem, thoughtfully considered.',copy:'Sample shop policy: seasonal substitutions would preserve the palette, overall shape, and value of your bouquet. Photos are illustrative. For a future live shop, a damaged or incorrect arrangement should be reported to the studio with photographs within 24 hours of delivery so a replacement or refund can be assessed. Actual refund terms must be confirmed before launch. No real sales or returns are processed in this prototype.'},privacy:{title:'Your moments stay yours.',copy:'This prototype keeps your bag, gift messages, delivery ZIP, and sample subscription preference in local storage on this browser. It does not request payment details, names, or street addresses and has no analytics or newsletter tracking. Gift messages are not sent to the studio. Remove items from your bag or clear this site’s browser data to delete stored choices. Hosting infrastructure may process ordinary technical access logs. A live shop will need its own published privacy policy.'},terms:{title:'A little transparency.',copy:'Petal & Stem is a fictional florist and this is an interactive prototype. Products, prices, availability, delivery areas, opening hours, and contact information are illustrative. All prices are sample US dollars. Floral imagery was created for this concept. You cannot place an order, start a subscription, or make a payment here. Saving a bag or plan does not reserve flowers, confirm a delivery, or enter into a purchase. Live payment, stock, tax, customer support, and delivery services must be connected before launch.'}};
function showPolicy(key){const policy=policies[key];if(!policy)return;$('#info-content').innerHTML=`<h2 id="info-title">${policy.title}</h2><p>${policy.copy}</p><button class="button" data-close>Back to the flowers <span aria-hidden="true">↗</span></button>`;openDialog('info-dialog');}

function updateSubscription(){const values=new FormData($('#subscription-form')),price=values.get('plan')==='classic'?58:42;$('#subscription-summary').innerHTML=`<strong>${values.get('frequency')} flowers · ${money(price)} per delivery</strong>${values.get('plan')==='classic'?'20–25':'12–15'} seasonal stems, chosen by the florist.<br>With sample local delivery: ${money(price+6)}–${money(price+9)} each time.<br>Sample area: Portland ZIP codes 97201–97206. Vase not included.`;}
$('#subscription-form').addEventListener('change',updateSubscription);
$('#subscription-form').addEventListener('submit',event=>{event.preventDefault();const plan=Object.fromEntries(new FormData(event.target));const saved=saveStorage('petal-stem-plan-v1',plan);toast(saved?'Your sample plan is saved. No subscription has been started.':'Your sample plan is available for this visit only.');closeDialog($('#subscription-dialog'));});
function openSubscription(){const saved=readStorage('petal-stem-plan-v1',{});if(['Weekly','Fortnightly','Monthly'].includes(saved.frequency))$(`#subscription-form [name="frequency"][value="${saved.frequency}"]`).checked=true;if(['petite','classic'].includes(saved.plan))$(`#subscription-form [name="plan"][value="${saved.plan}"]`).checked=true;updateSubscription();openDialog('subscription-dialog');}

function route(initial=false){let hash;try{hash=decodeURIComponent(location.hash.slice(1)||'home');}catch{hash='home';}const productId=hash.startsWith('bouquet/')?hash.slice(8):null;$$('dialog[open]').forEach(closeDialog);$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Open menu');if(productId){const p=getProduct(productId);$('#home-view').hidden=true;$('#product-view').hidden=false;if(p){renderProduct(p);window.scrollTo({top:0,behavior:'instant'});if(!initial)$('#product-view h1').focus({preventScroll:true});}else{$('#product-view').innerHTML='<div class="section-wrap"><h1>That flower has wandered off.</h1><p>We couldn’t find this bouquet. There are lovely things waiting in the collection.</p><a class="button" href="#collection">See the flowers →</a></div>';document.title='Bouquet not found — Petal & Stem';}return;}
currentProduct=null;$('#home-view').hidden=false;$('#product-view').hidden=true;document.title='Petal & Stem — Flowers, with feeling.';if(hash==='home'){window.scrollTo({top:0,behavior:'instant'});}else{const target=document.getElementById(hash);if(target){if(target.tagName==='DETAILS')target.open=true;requestAnimationFrame(()=>target.scrollIntoView({behavior:initial?'instant':'smooth',block:'start'}));}}
}
window.addEventListener('hashchange',()=>route());
document.addEventListener('click',event=>{const close=event.target.closest('[data-close]');if(close)closeDialog(close.closest('dialog'));const photo=event.target.closest('[data-photo]');if(photo){$('#gallery-main').src=`assets/${photo.dataset.photo}.webp`;$('#gallery-main').alt=photo.dataset.photo.endsWith('-detail')?`An overhead view of ${currentProduct.name} laid on the studio workbench, showing its flowers and paper wrapping`:currentProduct.alt;$$('[data-photo]').forEach(button=>button.setAttribute('aria-pressed',String(button===photo)));$('#gallery-caption').textContent=photo.dataset.photo.endsWith('-detail')?'A closer look at the Classic bouquet. Each arrangement is one of a kind.':'The Classic size, wrapped and ready to give. Vase not included.';}
const occasion=event.target.closest('[data-occasion]');if(occasion){resetFilters();$('#filters [name="occasion"]').value=occasion.dataset.occasion;showFilters();renderCollection();location.hash='collection';}
const policy=event.target.closest('[data-policy]');if(policy)showPolicy(policy.dataset.policy);
const bagButton=event.target.closest('[data-bag-command]');if(bagButton)bagCommand(bagButton);
const button=event.target.closest('[data-action]');if(!button)return;switch(button.dataset.action){case'bag':renderBag();openDialog('bag-dialog');break;case'menu':{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close menu':'Open menu');break;}case'filters':showFilters($('#filters').hidden);break;case'all-flowers':resetFilters();showFilters();$('#collection').scrollIntoView({behavior:'smooth'});break;case'reset-filters':resetFilters();break;case'finder':openFinder();break;case'finder-restart':finder.step=0;renderFinder();focusFinder();break;case'finder-back':finder.step=Math.max(0,finder.step-1);renderFinder();focusFinder();break;case'check-zip':checkZip();break;case'review':reviewBag();break;case'subscription':openSubscription();break;}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#mobile-nav').hidden){$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Open menu');$('.menu-button').focus();}});
window.addEventListener('storage',event=>{if(event.key===BAG_KEY){bag=sanitizeBag(readStorage(BAG_KEY,[]));updateBagCount();if($('#bag-dialog').open)renderBag();}});
$('#copyright-year').textContent=new Date().getFullYear();
renderCollection();updateBagCount();route(true);
